import { T } from '../src/localize.ts';
import type { Activity, Localized } from '../src/types.ts';

// Micro-lessons with one check question: interview answers, CVs and letters, and a
// job-search plan series. General advice only: no statistics, market data or legal
// rules; anything official is "check the official site".

type Tri = { en: string; uz: string; ru: string };
const L = (en: string, uz: string, ru: string): Localized => ({ en, uz, ru });
const tri = (en: string, uz: string, ru: string): Tri => ({ en, uz, ru });

interface Def { id: string; node: string; minutes?: number; title: Localized; body: Localized; example: Tri; check: { prompt: Tri; options: Tri[]; answer: number; explanation: Localized } }
const lesson = (def: Def): Activity => ({
  id: def.id, kind: 'lesson', node: def.node, levels: [1, 5], minutes: def.minutes ?? 4, title: def.title, body: def.body, example: T(def.example),
  check: { prompt: T(def.check.prompt), options: def.check.options.map((option) => T(option)), answer: def.check.answer, explanation: def.check.explanation },
});

